 returnResolution(actor:Identity,organizationId:string,schoolId:string,input:Parameters<CoordinationRepository['returnResolution']>[3]){return this.transition(actor,{organizationId,schoolId},input,{command:'CoordinationResolutionReturned',capability:'coordination.verify',from:['AWAITING_VERIFICATION'],to:'IN_PROGRESS',event:'RETURNED',clearResolution:true,denyProposer:true});}
