 async grant(operator:OperatorPrincipal,input:{organizationId:string;schoolId:string;accountId:string;capability:CoordinationCapability}){if(operator.verified!==true||!coordinationCapabilities.includes(input.capability))throw new AccessError('FORBIDDEN');this.enabled();return this.run(async tx=>{const membership=await tx.schoolMembership.findFirst({where:{organizationId:input.organizationId,schoolId:input.schoolId,accountId:input.accountId,status:'ACTIVE'},select:{id:true}});if(!membership)throw new AccessError('NOT_FOUND');const at=this.now(),grant=await tx.coordinationCapabilityGrant.upsert({where:{organizationId_schoolId_accountId_capability:{organizationId:input.organizationId,schoolId:input.schoolId,accountId:input.accountId,capability:input.capability}},create:{id:randomUUID(),...input,membershipId:membership.id,grantedByOperatorId:operator.operatorId,grantedAt:at,version:1},update:{membershipId:membership.id,grantedByOperatorId:operator.operatorId,grantedAt:at,revokedAt:null,version:{increment:1}}});await tx.operatorAuditEntry.create({data:{id:randomUUID(),operatorId:operator.operatorId,command:'GrantCoordinationCapability',resourceType:'CoordinationCapabilityGrant',resourceId:grant.id,occurredAt:at,details:{schemaVersion:1,organizationId:input.organizationId,schoolId:input.schoolId,accountId:input.accountId,capability:input.capability}}});return {grantId:grant.id,version:grant.version};},'Serializable');}
